'use strict';
const SearchText = (() => {
  const normalize = value => String(value).toLocaleLowerCase('en-US').replace(/[–—−]/g, '-').replace(/\s+/g, ' ').trim();
  const terms = query => [...new Set(normalize(query).split(' ').filter(Boolean))];
  const score = (item, words) => {
    const title = normalize(item.title);
    const body = normalize(item.text);
    if (!words.length || !words.every(word => (title + ' ' + body).includes(word))) return 0;
    return 1 + words.reduce((total, word) => total + (title.includes(word) ? 10 : 0), 0);
  };
  const excerpt = (text, words, length = 260) => {
    const clean = String(text).replace(/\s+/g, ' ').trim();
    const lower = normalize(clean);
    const positions = words.map(word => lower.indexOf(word)).filter(i => i >= 0);
    const match = positions.length ? Math.min(...positions) : 0;
    let start = Math.max(0, match - 75);
    if (start > 0) {
      const space = clean.indexOf(' ', start);
      if (space >= 0 && space < match) start = space + 1;
    }
    return (start ? '…' : '') + clean.slice(start, start + length) + (start + length < clean.length ? '…' : '');
  };
  return {normalize, terms, score, excerpt};
})();

const speakerTopics={"all":"All topics","design":"Design and direction","staffing":"Staffing and patrol","landscaping":"Landscaping","netting":"Netting and rescue","technology":"Technology","effectiveness":"Effectiveness and substitution"};
const speakers={"madison":{"name":"Steve Madison","remarks":[{"id":"madison-2018-motion","sortOrder":1,"title":"Moving the permanent-barrier recommendation","meeting":"v2018","time":"01:39:51","topic":"design","quote":null,"context":"Madison moved approval of the task-force recommendation. Hampton seconded it, and the Council approved it unanimously.","earlier":"The multidisciplinary task force had considered physical and complementary measures, including netting, landscaping, staffing, and technology.","response":"The adopted direction centered on a permanent physical barrier. The detailed design still had to be developed.","outcome":"This establishes the earlier policy choice against which later design and alternatives discussions can be read.","links":[{"label":"Adopted motion","source":"m2018","page":5},{"label":"Task-force recommendation","source":"r2018"}],"refs":"5–7","kind":"Recorded action","basis":"The action is documented in the official Council minutes, page 5, and retained Source 6. The time marks the approximate motion-and-approval sequence, not a verbatim statement by Madison.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"},{"id":"madison-coupling","title":"Explaining why interrupting access can matter","meeting":"v2021","time":"01:03:49","topic":"effectiveness","quote":"really disruptive action is required to be able to prevent the suicide","context":"Madison discussed Malcolm Gladwell’s account of coupling between a place and a method and explained why disrupting that relationship mattered to the bridge.","earlier":"Public Health had addressed regional effects and substitution during the April 2018 Council discussion.","response":"Madison treated prevention as an important goal while also saying the permanent design was not ready for a decision.","outcome":"He proposed narrowing the field to two choices and obtaining more community input. Gladwell’s general-reader account is separate from the original intervention studies.","links":[{"label":"Earlier Public Health discussion","source":"v2018","time":"01:27:14"},{"label":"Madison on narrowing the options","source":"v2021","time":"01:08:35"}],"refs":"11, 32","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"madison-two-options","title":"Narrow to two choices, then seek more input","meeting":"v2021","time":"01:08:35","topic":"design","quote":"what we should try to do is get down to two choices","context":"Madison said the City had either not found the right solution or had not had enough process to identify it. He proposed narrowing the alternatives before returning to the community.","earlier":"Staff had brought the results of commission review and full-scale mockups. The committee was being asked how to proceed with the designs.","response":"Gordo later said he was not ready even to narrow the process and asked for more options.","outcome":"The committee did not select a design. Madison also described the temporary solution as inelegant but effective, which he thought allowed time for further consideration.","links":[{"label":"Staff report and advisory feedback","source":"r2021"},{"label":"Temporary-fence comment","source":"v2021","time":"01:08:59"},{"label":"Gordo’s response on narrowing","source":"v2021","time":"01:21:36"}],"refs":"9, 11","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"madison-staffing-2021","title":"The practical limits of intervention by personnel","meeting":"v2021","time":"01:36:11","topic":"staffing","quote":"the efficacy of it is really hard to to predict","context":"Madison said he had discussed staffing with residents and staff. He questioned whether personnel would be in the right place and able to act when needed.","earlier":"Hampton had asked about continuous staffing, Mermell had responded, and Gordo had proposed a host or guide model.","response":"Madison identified the bridge’s length, curvature, two sides, and varied incident timing. The discussion also raised the limits of physical intervention and liability.","outcome":"The same practical issue returned when Madison described rapidly unfolding incidents in November 2023. This was a discussion of feasibility, not a measured trial of staffing at this bridge.","links":[{"label":"Gordo’s preceding proposal","source":"v2021","time":"01:31:59"},{"label":"Later response-time discussion","source":"v2023","time":"00:52:29"}],"refs":"11, 15","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"madison-safety","title":"Safety and the bridge’s appearance","date":"November 15, 2023","time":"00:29:07","meeting":"v2023","kind":"Quotation","quote":"elevate human safety over aesthetics and objects","context":"Madison said the proposed designs would change the bridge’s appearance. He also said that a solution achieving both safety and preservation goals would be more successful.","outcome":"He later asked about netting and landscaping and was not ready to support one of the three designs.","basis":"Quoted in the retained research account. The timestamp is the approximate start of the surrounding passage.","refs":"14","topic":"design","earlier":"The Council had directed a vertical-barrier design process in April 2018. A first design cycle and full-scale mockups preceded the three new concepts presented in 2023.","response":"Staff described rescue, maintenance, and preservation concerns associated with horizontal netting. The later exchange addressed landscaping and the bridge’s geometry.","links":[{"label":"Earlier Council decision","source":"m2018","page":5},{"label":"Staff and consultant responses","source":"v2023","time":"00:29:29"},{"label":"Three proposed concepts","source":"p2023"}],"sortDate":"2023-11-15","body":"Public Safety Committee"},{"id":"madison-trees","title":"Returning to trees and shrubs below the bridge","meeting":"v2023","time":"00:33:24","topic":"landscaping","quote":"have we looked at even solutions as simple as, you know, thick trees and shrubs and bushes that would then break a fall?","context":"Madison asked about landscaping as a cushioning or deterrent measure while exploring a combination of approaches.","earlier":"The April 2018 report said no verifying scientific data had been found for that role. About one-fifth of the span, including its highest point, could not be planted. It treated trees as a possible supplement.","response":"Markarian said the task force had examined landscaping and researched measures elsewhere. Staff and the consultant discussed the local geometry, remaining fall distance, structural demands, and appearance of netting.","outcome":"Madison continued to favor studying a combined approach and remained unwilling to support the three proposed designs.","links":[{"label":"Earlier landscaping finding","source":"r2018","page":3},{"label":"2018 presentation of planting limits","source":"v2018","time":"01:04:17"},{"label":"Staff’s response","source":"v2023","time":"00:33:47"},{"label":"Later position on the designs","source":"v2023","time":"00:40:13"}],"refs":"5, 14","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"madison-not-ready","title":"Declining to support the three proposed designs","meeting":"v2023","time":"00:40:13","topic":"design","quote":"I don’t think I could support any of these options","context":"After the discussion of netting and landscaping, Madison said a substantial change in community sentiment would be needed for him to support one of the designs. He had suggested the temporary fence might be preferable.","earlier":"Staff had explained the prior alternatives work and site-specific constraints. The new design cycle had brought three concepts.","response":"Olmos proposed completing commission review, presenting survey results, and returning with additional information about netting and other questions.","outcome":"This was an explicit statement about the presented designs. It does not establish that Madison rejected every research finding discussed at the meeting.","links":[{"label":"Preceding alternatives exchange","source":"v2023","time":"00:33:24"},{"label":"Jones on continuing the process","source":"v2023","time":"00:55:35"},{"label":"Staff’s closing proposal","source":"v2023","time":"01:02:09"}],"refs":"14","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"madison-response","title":"Could stationed personnel respond in time?","date":"November 15, 2023","time":"00:52:29","meeting":"v2023","kind":"Quotation","quote":"unfold in five minutes","context":"Madison used this phrase while questioning whether personnel stationed along the bridge could reach an incident quickly enough. He had also discussed how capital funds might support an ongoing staffing expense.","outcome":"The committee requested more staffing analysis. Staff treated personnel as a possible supplement to a physical barrier.","basis":"Quotation retained in the research account. The author checked this exchange’s speaker handoffs and locators against the video. The displayed time starts Madison’s passage, not the exact quoted phrase.","refs":"15","topic":"staffing","earlier":"Madison had raised the bridge’s length, curvature, and unpredictable incident timing during the August 2021 staffing discussion. Markarian had just repeated coverage and liability concerns in 2023.","response":"Gordo acknowledged the response-time concern but asked whether the presence of personnel could deter an impulsive attempt. Olmos described patrol as a complementary measure.","links":[{"label":"Madison’s earlier practical concerns","source":"v2021","time":"01:36:11"},{"label":"Markarian’s staffing response","source":"v2023","time":"00:47:01"},{"label":"Gordo follows up","source":"v2023","time":"00:53:38"}],"sortDate":"2023-11-15","body":"Public Safety Committee"},{"id":"madison-health-expertise","title":"Asking for Public Health at the next discussion","meeting":"v2023","time":"01:01:34","topic":"effectiveness","quote":"public health needs to be involved in this discussion","context":"Madison called for health expertise after Olmos and Markarian explained that a barrier can buy time for a crisis to ease or responders to arrive.","earlier":"Public Health and mental-health participants had been involved in the earlier process. Jones had just asked about their role and substitution.","response":"Staff said they had consulted people in the field and proposed bringing health professionals with the survey results and follow-up information.","outcome":"The July 2024 meeting included Sandri Kramer of Didi Hirsch, who explained means restriction and the importance of time for intervention.","links":[{"label":"Jones’s preceding question","source":"v2023","time":"00:56:47"},{"label":"Barrier buys time exchange","source":"v2023","time":"01:00:41"},{"label":"Markarian on time for responders","source":"v2023","time":"01:01:26"},{"label":"Kramer’s July discussion","source":"v2024","time":"00:42:08"}],"refs":"14, 18–19","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"madison-life","title":"Human life and safety","date":"July 17, 2024","time":"01:03:10","meeting":"v2024","kind":"Transcript excerpt","quote":"we have to elevate human life and human safety over really objects of any kind","context":"Madison expressed sympathy to a family and recalled why the emergency fence had been installed. He remained uncertain that the proposed permanent designs had sufficiently changed.","outcome":"He later asked about ground cover and layered netting. No permanent design was sent to the full Council at this meeting.","basis":"Wording from the preserved working transcript. The approximate player locator is retained in the reviewed source note. This website update did not add a new word-for-word listening check.","refs":"18, 22","topic":"design","earlier":"The July presentation returned with patrol costs, technology analysis, netting and rescue review, Golden Gate consultation, survey results, and prevention expertise requested during earlier discussions.","response":"Madison also acknowledged public-safety concerns about netting while asking whether the City had exhausted alternatives.","links":[{"label":"Material returned to the committee","source":"p2024"},{"label":"Later ground-cover exchange","source":"v2024","time":"01:06:01"}],"sortDate":"2024-07-17","body":"Public Safety Committee"},{"id":"madison-ground-cover","title":"Have all the options been exhausted?","meeting":"v2024","time":"01:06:01","topic":"landscaping","quote":"Do you feel like we’ve really done our level best to exhaust all the options?","context":"Madison asked about ground cover in combination with other measures, consultation with Caltech, and whether the City had fully explored the alternatives.","earlier":"Landscaping had been addressed by the 2018 task force and again in November 2023. The July meeting returned with the requested wider engineering and rescue review.","response":"Markarian described seven years of work and said, “we have truly exhausted looking at various mitigation measures.” In the later ground-cover exchange, she explained why the fall distance limited measures at ground level.","outcome":"Madison continued to ask about combined measures and then a layered-net concept. The proposals were related to earlier questions but were not identical.","links":[{"label":"2018 landscaping finding","source":"r2018","page":3},{"label":"November 2023 question","source":"v2023","time":"00:33:24"},{"label":"Markarian describes the work","source":"v2024","time":"01:06:47"},{"label":"Ground-level response","source":"v2024","time":"01:10:37"},{"label":"Layered-net follow-up","source":"v2024","time":"01:11:27"}],"refs":"5, 14, 18, 22","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"madison-layered-nets","title":"Asking about layered netting and its effectiveness","meeting":"v2024","time":"01:11:27","topic":"netting","quote":"I think my question was more about the efficacy and whether it was considered","context":"Madison proposed more than one layer of netting with ground cover. After hearing about cost and engineering complexity, he said his question concerned effectiveness and whether the idea had been considered.","earlier":"The committee had received the site-specific review of a horizontal net and Fire’s rescue concerns. Earlier landscaping findings did not evaluate this exact layered configuration.","response":"Markarian described the added structural reach. The architect described cost, appearance, and engineering complexity and said the concept was not impossible.","outcome":"The exchange supplied further design information but did not establish a feasible or approved system. No permanent design was sent to the full Council.","links":[{"label":"Question about layers","source":"v2024","time":"01:11:27"},{"label":"Staff and architect responses","source":"v2024","time":"01:12:18"},{"label":"Madison’s quoted follow-up","source":"v2024","time":"01:13:35"},{"label":"July presentation","source":"p2024"}],"refs":"16, 18, 22","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"}]},"gordo":{"name":"Victor Gordo","remarks":[{"id":"gordo-2018-regional","title":"Would deaths fall across the region or move elsewhere?","meeting":"v2018","time":"01:31:15","topic":"effectiveness","quote":null,"context":"Gordo asked whether a bridge barrier would reduce deaths across the region or simply change where they occurred. He then asked about the supporting study.","earlier":"Wilson had raised substitution earlier in the same discussion. Public Health Director Michael Johnson had begun explaining the research.","response":"Johnson said the research showed an overall decline after barriers were installed and referred to a Toronto study.","outcome":"The Council proceeded with the task-force recommendation. Similar substitution questions returned in 2023. Successive studies and different outcomes still require separate interpretation.","links":[{"label":"Earlier Public Health answer","source":"v2018","time":"01:27:14"},{"label":"Johnson answers Gordo","source":"v2018","time":"01:31:51"},{"label":"Gordo asks about the study","source":"v2018","time":"01:32:08"},{"label":"Johnson resumes","source":"v2018","time":"01:32:15"}],"refs":"7","kind":"Discussion summary","basis":"Summary of the recorded discussion retained in the sent research account and source note. The player locators are inherited at their documented scope. This is not a verbatim quotation or a new listening check.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"},{"id":"gordo-decoupling","title":"The temporary fence and the bridge’s reputation","date":"August 18, 2021","time":"01:21:22","meeting":"v2021","kind":"Quotation","quote":"the decoupling, if you will, has started","context":"Gordo picked up Madison’s discussion of place and method. He said the temporary structure appeared to be discouraging people from using the bridge to harm themselves.","outcome":"He also said the committee was not ready to narrow the permanent designs and called for more options and public input.","basis":"Quoted wording and locator retained in the reviewed account of the official recording. This is Gordo’s interpretation of the local record, not a new causal estimate.","refs":"11","topic":"effectiveness","earlier":"Madison had discussed the relationship between a particular place, an immediate crisis, and access to a method. The temporary fence had been installed in 2018.","response":"Gordo interpreted the local record as evidence of deterrence while saying the work was incomplete. His statement is an interpretation of descriptive local counts, not an independently established causal result.","links":[{"label":"Madison’s earlier discussion","source":"v2021","time":"01:03:49"},{"label":"Gordo on narrowing the designs","source":"v2021","time":"01:21:36"}],"sortDate":"2021-08-18","body":"Public Safety Committee"},{"id":"gordo-more-options","title":"More options and another round of public input","meeting":"v2021","time":"01:21:36","topic":"design","quote":"we ought to send this back for more community input","context":"Gordo said he was not ready to narrow the permanent designs. He discussed different materials and further consideration of the enclosure concept.","earlier":"The 2018 policy direction, the first design cycle, and commission review preceded this request. Madison had proposed reducing the field to two choices.","response":"The enclosure study had already produced additional design information. Gordo’s discussion concerned both materials and the opportunity for community input.","outcome":"Further design work and input followed. The repeated “get it right” phrases appeared within these specific requests.","links":[{"label":"Earlier design comparison","source":"v2021","time":"00:48:33"},{"label":"More-options request","source":"v2021","time":"01:22:23"},{"label":"Later community-input passage","source":"v2021","time":"01:23:41"},{"label":"Staff’s closing response","source":"v2021","time":"01:43:48"}],"refs":"9, 11","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"gordo-host-program","title":"A host or guide model for the bridge","meeting":"v2021","time":"01:31:59","topic":"staffing","quote":"I don’t think we should dismiss outright the concept of achieving our goal of suicide prevention by manning the bridge","context":"Gordo drew on the Old Pasadena host or guide program and suggested personnel who could observe, report, and offer historical information.","earlier":"Mermell had just said staffing was previously suggested and questioned its feasibility as the solution.","response":"Madison discussed visibility, the size of the bridge, incident timing, and whether personnel should physically intervene.","outcome":"Gordo later clarified that he also had a hybrid of a physical measure and staffing in mind. A program used in Old Pasadena did not itself establish effectiveness for bridge suicide prevention.","links":[{"label":"Mermell’s preceding answer","source":"v2021","time":"01:27:11"},{"label":"Madison’s response","source":"v2021","time":"01:36:11"},{"label":"Gordo’s hybrid clarification","source":"v2021","time":"01:45:08"}],"refs":"11","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"gordo-hybrid","title":"Clarifying a combined physical and staffing approach","meeting":"v2021","time":"01:45:08","topic":"staffing","quote":"maybe it’s a hybrid","context":"Gordo clarified that his interest in staffing could involve combining it with a physical design and the more transparent material shown that evening.","earlier":"Staff and committee members had discussed coverage, intervention, cost, and liability concerns.","response":"Mermell’s closing summary called for consultation with the design team and a further timetable. He said a three-month return was probably too aggressive.","outcome":"The clarification matters because the staffing discussion included both a possible alternative and a possible complement to physical protection.","links":[{"label":"Staff’s timetable response","source":"v2021","time":"01:43:48"},{"label":"Earlier staffing discussion","source":"v2021","time":"01:31:59"}],"refs":"11","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"gordo-staffing","title":"Revisiting a staffing model","date":"November 15, 2023","time":"00:51:52","meeting":"v2023","kind":"Quotation","quote":"money well spent","context":"Gordo suggested that people affected by suicidal crises might view a staffing expense of “a couple hundred thousand dollars” this way. He asked staff to revisit the model and return with recommendations.","outcome":"Markarian had explained cost, coverage, liability, and off-hours concerns. Gordo later requested mental-health input on whether a visible human presence could deter an impulsive attempt.","basis":"Quoted fragments and the passage locator are retained in the source note. The author checked the speaker handoffs and times against the official video. This oral amount was not an approved staffing budget.","refs":"15","topic":"staffing","earlier":"Gordo had proposed a guide or host model in August 2021. In this meeting, Markarian again described continuous coverage, multiple personnel, liability, and incidents outside ordinary working hours.","response":"Gordo asked staff to return with recommendations despite those concerns. The later discussion separated immediate response from a possible deterrent effect of human presence.","links":[{"label":"Gordo’s 2021 proposal","source":"v2021","time":"01:31:59"},{"label":"Markarian’s earlier answer that evening","source":"v2023","time":"00:47:01"},{"label":"Follow-up about mental-health advice","source":"v2023","time":"00:53:38"}],"sortDate":"2023-11-15","body":"Public Safety Committee"},{"id":"gordo-presence","title":"Requesting expert advice on the deterrent effect of human presence","meeting":"v2023","time":"00:53:38","topic":"staffing","quote":"I would ask that staff talk with professionals, psychologists and psychiatrists to see if in fact that might make a difference","context":"Gordo distinguished an immediate response from the possibility that a visible human presence might prevent an impulsive attempt from beginning. He asked for professional advice.","earlier":"Markarian had explained the earlier staffing assessment. Madison had just questioned whether personnel could respond quickly enough.","response":"Olmos said patrol and technology could enhance a barrier and asked whether to continue the design process or pause.","outcome":"Commission review and the survey were to continue, with additional responses and health expertise when the project returned.","links":[{"label":"Staff’s earlier staffing assessment","source":"v2023","time":"00:47:01"},{"label":"Madison’s response-time concern","source":"v2023","time":"00:52:29"},{"label":"Olmos asks for direction","source":"v2023","time":"00:54:37"},{"label":"Next steps","source":"v2023","time":"01:02:09"}],"refs":"14–15","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"gordo-rescue-clarification","title":"Clarifying which design raised Fire’s rescue concerns","meeting":"v2024","time":"01:08:36","topic":"netting","quote":null,"context":"Gordo asked whether Fire’s concern about risks to people and responders applied to vertical mesh.","earlier":"Fire’s earlier presentation had discussed the difficulties of rescues involving a horizontal net.","response":"Fire clarified that the concern was about horizontal netting and explicitly supported a vertical barrier. Gordo acknowledged the clarification.","outcome":"This exchange helps distinguish opposition to a particular local net design from opposition to physical protection generally.","links":[{"label":"Fire’s earlier assessment","source":"v2024","time":"00:34:00"},{"label":"Fire’s clarification","source":"v2024","time":"01:09:16"}],"refs":"18","kind":"Discussion summary","basis":"Summary of the preserved City-caption exchange, approximately 01:08:36 to 01:09:40, with the speaker handoff naming the mayor. These are caption-derived passage locators, not newly verified audio boundaries.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"gordo-remote-intervention","title":"Requesting a closer look at remote intervention","meeting":"v2024","time":"01:14:21","topic":"technology","quote":"I’d ask the experts to look at that technology","context":"Gordo described monitored cameras with speakers that could allow a trained person to engage someone on the bridge in real time.","earlier":"Technology and staffing had been studied previously and revisited after the November 2023 discussion. Hampton had also just suggested cameras and motion detection.","response":"In the following exchange with Jones, Markarian described such measures as complements, discussed operational limits, and questioned their effectiveness alone.","outcome":"Gordo offered to pass along information. This was a request to examine an application of technology, not a demonstrated substitute for physical protection.","links":[{"label":"Hampton’s earlier suggestion","source":"v2024","time":"01:00:30"},{"label":"Technology review","source":"p2024"},{"label":"Staff response during Jones’s questions","source":"v2024","time":"01:16:54"}],"refs":"16, 18","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"}]},"hampton":{"name":"Tyron Hampton","remarks":[{"id":"hampton-2018-action","sortOrder":2,"title":"Supporting the barrier direction and interim fencing","meeting":"v2018","time":"01:39:51","topic":"design","quote":null,"context":"The official minutes record Hampton’s request to consider temporary fencing at the bridge’s ends and approaches until an approved design could be built. He also seconded the staff recommendation.","earlier":"The task force recommended physical protection while treating other measures as possible supplements.","response":"The Council unanimously approved the recommendation moved by Madison.","outcome":"Hampton’s support for interim protection and the permanent direction forms part of the earlier record.","links":[{"label":"Hampton’s request and the Council action","source":"m2018","page":5},{"label":"Task-force recommendation","source":"r2018"}],"refs":"5–7","kind":"Recorded action","basis":"The request and second are documented in the official Council minutes, page 5. The displayed recording time locates the motion-and-approval sequence only. It is not an exact timestamp for Hampton’s separate temporary-fencing request.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"},{"id":"hampton-right","title":"Further consideration in 2021","date":"August 18, 2021","time":"01:26:03","meeting":"v2021","kind":"Quotation","quote":"get this right","context":"Hampton said the temporary structure was working and continued considering alternatives for a permanent approach. His proposal for around-the-clock staffing followed at 01:26:44.","outcome":"Mermell responded that staffing had been considered and was not feasible as a replacement. Further examination of a complementary staffing role remained in the discussion.","basis":"Quoted phrase and locator retained in the reviewed source note. The phrase alone does not establish that the requested consideration was redundant.","refs":"11","topic":"design","earlier":"The meeting followed commission review and full-scale mockups. Staff had also developed an enclosure concept in response to earlier direction.","response":"Hampton praised staff’s work, supported further consideration, and asked whether an enclosure could take a form more compatible with the historic bridge.","links":[{"label":"Refined design-goal comparison","source":"v2021","time":"00:48:33"},{"label":"Staff’s closing summary","source":"v2021","time":"01:43:48"}],"sortDate":"2021-08-18","body":"Public Safety Committee"},{"id":"hampton-24-hours","title":"Asking whether the bridge could be staffed around the clock","meeting":"v2021","time":"01:26:44","topic":"staffing","quote":"Has that ever even come up?","context":"Hampton asked whether staffing the bridge for 24 hours had been considered and what two-person coverage would cost.","earlier":"The task force had considered complementary measures. The committee was discussing a permanent design after the mockup reviews.","response":"Mermell said staffing had been suggested before, gave a rough annual cost in the hundreds of thousands, and questioned its feasibility. He favored retaining the temporary fence until another solution was ready.","outcome":"Gordo then developed a host or guide model, while Madison raised practical intervention concerns. No staffing program was approved in this exchange.","links":[{"label":"Mermell’s response","source":"v2021","time":"01:27:11"},{"label":"Gordo’s guide proposal","source":"v2021","time":"01:31:59"},{"label":"Madison’s practical concerns","source":"v2021","time":"01:36:11"}],"refs":"11","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"hampton-urgency","title":"Asking for a faster return","date":"July 17, 2024","time":"00:58:57","meeting":"v2024","kind":"Transcript excerpt","quote":"I think that time is of the essence.","context":"Hampton asked for direction and a return to the committee in roughly 90 days rather than early the following year.","outcome":"He named vertical mesh as his preferred design at 00:59:36 and also raised cameras and motion detection as possible supplements.","basis":"Wording from the preserved working transcript. The player locator and the substance of the request are retained in the reviewed source note and minutes. No new word-for-word listening check was performed for this website.","refs":"20","topic":"design","earlier":"The proposed schedule anticipated further design work, public feedback, commission review, and a return to Public Safety early in 2025.","response":"Hampton asked for a shorter return interval and gave a design preference. His requested 90 days was not a completed milestone or a construction deadline.","links":[{"label":"Vertical mesh preference","source":"v2024","time":"00:59:36"},{"label":"Meeting minutes","source":"m2024"}],"sortDate":"2024-07-17","body":"Public Safety Committee"},{"id":"hampton-mesh","title":"Naming vertical mesh as a preferred design","meeting":"v2024","time":"00:59:36","topic":"design","quote":"I think the vertical mesh is the most ideal","context":"Hampton identified vertical mesh as his preference and discussed its appearance and the bridge’s public identity.","earlier":"Staff’s remaining concepts were vertical webmesh and metal pickets. The committee also had the fuller netting, patrol, and prevention review.","response":"Hampton accompanied his preference with a request for a faster return and possible camera and motion-detection measures.","outcome":"Later in the meeting, he still asked to keep horizontal netting in consideration. Both statements belong in the record.","links":[{"label":"Request for a faster return","source":"v2024","time":"00:58:57"},{"label":"Technology suggestion","source":"v2024","time":"01:00:30"},{"label":"Later position on netting","source":"v2024","time":"01:21:29"}],"refs":"16, 20–21","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"hampton-cameras","title":"Cameras and motion detection as added protection","meeting":"v2024","time":"01:00:30","topic":"technology","quote":"we need to put cameras up on the bridge with motion detectors","context":"Hampton proposed camera and sensor alerts to Police as an addition to the vertical mesh he had just preferred.","earlier":"The task force had considered technology, and the July presentation returned with further technology analysis.","response":"The meeting’s later staff response treated technology as a potential complement to physical protection and raised operational concerns.","outcome":"This was a suggestion for additional protection, not proof of an approved camera system or its measured effectiveness.","links":[{"label":"Technology and other measures reviewed","source":"p2024"},{"label":"Later staff response on complementary tools","source":"v2024","time":"01:16:54"}],"refs":"16, 18, 20","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"hampton-patrol-again","title":"Returning to netting and continuous patrol","meeting":"v2024","time":"01:19:40","topic":"staffing","quote":"I still think that those are factors that we should put out","context":"Hampton said he had raised horizontal netting and continuous patrol at the previous meeting and still wanted them considered, while acknowledging cost.","earlier":"Jones had just asked about patrol and the netting recommendation. Markarian had given the reasons against patrol as a substitute and said the netting recommendation was unanimous.","response":"Hampton moved on to ask Fire about rescue cushions and whether a higher-capacity version existed.","outcome":"He retained an interest in these measures alongside his earlier preference for vertical mesh and call to move forward.","links":[{"label":"Patrol answer","source":"v2024","time":"01:16:54"},{"label":"Netting answer","source":"v2024","time":"01:18:41"},{"label":"Rescue-cushion exchange","source":"v2024","time":"01:20:04"}],"refs":"18, 20–21","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"hampton-cushion","title":"A higher-capacity rescue cushion: a new unanswered question","meeting":"v2024","time":"01:20:55","topic":"netting","quote":null,"context":"After Fire described the limits of its rescue cushion, Hampton asked whether equipment rated for a greater height existed.","earlier":"Fire had said its cushion was rated for roughly 100 feet, while portions of the bridge reached roughly 150 feet, with positioning constraints below.","response":"Fire did not know whether a higher-capacity cushion was available and agreed to investigate.","outcome":"This was a question the City had not already answered. A May 2026 presentation listed a rescue cushion without a capacity rating, so it did not resolve the question.","links":[{"label":"Initial cushion question and Fire response","source":"v2024","time":"01:20:04"},{"label":"Higher-capacity question and response","source":"v2024","time":"01:20:55"}],"refs":"21","kind":"Discussion summary","basis":"Summary of the recorded discussion retained in the sent research account and source note. The player locators are inherited at their documented scope. This is not a verbatim quotation or a new listening check. The displayed time marks the surrounding follow-up, not an exact utterance boundary. The May 2026 record status is inherited from the retained source note, not a new equipment check.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"hampton-netting","title":"Keeping horizontal netting in consideration","date":"July 17, 2024","time":"01:21:29","meeting":"v2024","kind":"Transcript excerpt","quote":"the horizontal wouldn’t be an idea I’d tell you to completely cancel out","context":"Later in the same meeting, Hampton continued to favor considering horizontal netting after staff’s recommendation against it and Fire’s explanation of rescue concerns. He described it as the most attractive-looking option.","outcome":"He had also asked whether a higher-capacity rescue cushion existed. Staff did not know and agreed to investigate. That question was distinct from his preference for vertical mesh earlier in the meeting.","basis":"Wording from the preserved working transcript, with typographic apostrophes. The approximate player locator is retained in the reviewed source note. No new word-for-word listening check was performed for this website.","refs":"20–21","topic":"netting","earlier":"The expert review had not recommended horizontal netting. Fire had explained rescue and resource concerns, and staff had just repeated that the recommendation was unanimous.","response":"Hampton continued to favor keeping netting under consideration. He also said the project needed to move forward. The higher-capacity rescue-cushion question remained unanswered.","links":[{"label":"Fire’s rescue assessment","source":"v2024","time":"00:34:00"},{"label":"Unanimous recommendation clarified","source":"v2024","time":"01:18:41"},{"label":"Rescue-cushion exchange","source":"v2024","time":"01:20:04"}],"sortDate":"2024-07-17","body":"Public Safety Committee"}]},"jones":{"name":"Justin Jones","remarks":[{"id":"jones-other-options","title":"Asking what other options had been considered","meeting":"v2023","time":"00:41:34","topic":"design","quote":"Are there any other options that the working group looked into that you could share with us?","context":"Jones relayed residents’ concerns about both the existing fence and the proposed permanent designs and asked about other options.","earlier":"The Council had selected a vertical-barrier direction in 2018. Jones was not part of that decision or the 2021 committee discussion.","response":"Olmos explained that developing barrier designs was staff’s direction and that the other options had already gone through extensive discussion. Staff could study alternatives again if directed.","outcome":"Jones asked about the working group, costs, and survey and later supported continuing commission review.","links":[{"label":"Earlier Council direction","source":"m2018","page":5},{"label":"Olmos’s response","source":"v2023","time":"00:41:40"},{"label":"Jones on the next steps","source":"v2023","time":"00:55:35"}],"refs":"6, 12, 14","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The displayed time is an approximate passage locator. No new listening check was performed for this website.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"jones-continue","title":"Continuing commission review and the survey","date":"November 15, 2023","time":"00:55:35","meeting":"v2023","kind":"Caption excerpt","quote":"continue to go to the commissions and then get the results of the survey","context":"After Olmos asked whether staff should continue or pause, Jones recommended proceeding with commission review and hearing the survey results.","outcome":"Jones also asked about Public Health involvement and whether restricting access at one site shifted attempts elsewhere. Staff agreed to bring health professionals when the project returned.","basis":"Wording from the preserved City captions. The author’s completed recording check covers the speaker, passage, and approximate player locator. Caption cue starts differ slightly from that player locator.","refs":"14","topic":"design","earlier":"Olmos had asked whether to continue the planned process or pause to evaluate complementary measures. Staff had explained that the Council’s earlier direction was to develop vertical barriers.","response":"Jones supported continuing to the commissions and returning with the survey. Olmos’s closing proposal also included responses to the committee’s questions and health expertise.","links":[{"label":"Olmos asks for direction","source":"v2023","time":"00:54:37"},{"label":"Olmos’s proposed next steps","source":"v2023","time":"01:02:09"}],"sortDate":"2023-11-15","body":"Public Safety Committee"},{"id":"jones-public-health","title":"Public Health involvement and substitution","meeting":"v2023","time":"00:56:47","topic":"effectiveness","quote":null,"context":"Jones asked how Public Health had participated and whether blocking access at one bridge could shift attempts to another place. He also raised a broader citywide prevention approach.","earlier":"The Council had discussed substitution with Public Health in April 2018. That earlier answer concerned research, including a Toronto study.","response":"Olmos relayed the mental-health specialist’s explanation that interrupting access to a selected bridge would not simply send everyone to the next bridge. Staff agreed to bring health professionals when the project returned.","outcome":"The question recurred, but Jones was newer to the discussion. The staff explanation is distinct from a claim that every study finds no displacement at every location.","links":[{"label":"2018 Public Health discussion","source":"v2018","time":"01:27:14"},{"label":"Gordo’s 2018 follow-up","source":"v2018","time":"01:31:15"},{"label":"Olmos’s answer to Jones","source":"v2023","time":"00:57:36"},{"label":"Plan to bring health expertise","source":"v2023","time":"01:02:09"}],"refs":"7, 12, 14","kind":"Discussion summary","basis":"Summary of the recorded discussion retained in the sent research account and source note. The player locators are inherited at their documented scope. This is not a verbatim quotation or a new listening check.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"jones-patrol","title":"Patrol: cost, effectiveness, or both?","meeting":"v2024","time":"01:16:54","topic":"staffing","quote":null,"context":"Jones asked whether staff’s recommendation against continuous patrol was based on its cost or its effectiveness.","earlier":"The committee had requested further staffing analysis in November 2023. The July presentation estimated roughly $600,000 annually for private security and $1.16 million for law-enforcement coverage.","response":"Markarian said both cost and effectiveness were concerns, along with liability and training. She distinguished measures that might help from a replacement for physical protection.","outcome":"Jones then clarified the netting recommendation and supported pursuing one of the two remaining designs.","links":[{"label":"November 2023 request","source":"v2023","time":"00:51:52"},{"label":"Returned cost estimates","source":"p2024"},{"label":"Staff’s answer","source":"v2024","time":"01:17:12"},{"label":"Jones’s design position","source":"v2024","time":"01:18:55"}],"refs":"15–16, 18","kind":"Discussion summary","basis":"Summary of the recorded discussion retained in the sent research account and source note. The player locators are inherited at their documented scope. This is not a verbatim quotation or a new listening check.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"jones-netting-review","title":"Was any expert recommending horizontal netting?","meeting":"v2024","time":"01:18:41","topic":"netting","quote":null,"context":"Jones asked whether any expert or task-force participant was recommending horizontal netting.","earlier":"The July meeting had presented the expanded engineering and rescue review. Fire had explained why it could not recommend a net from a public-safety standpoint.","response":"Markarian answered that horizontal netting was unanimously not recommended.","outcome":"Jones accepted that clarification in the exchange and expressed support for pursuing one of the two remaining designs. This does not establish that nets are ineffective at other bridges.","links":[{"label":"Fire’s recommendation","source":"v2024","time":"00:35:48"},{"label":"Markarian’s answer","source":"v2024","time":"01:18:50"},{"label":"Jones supports proceeding","source":"v2024","time":"01:18:55"}],"refs":"16, 18","kind":"Discussion summary","basis":"Summary of the recorded discussion retained in the sent research account and source note. The player locators are inherited at their documented scope. This is not a verbatim quotation or a new listening check.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"jones-design","title":"Pursuing one of the two remaining designs","date":"July 17, 2024","time":"01:18:55","meeting":"v2024","kind":"Author-confirmed excerpt","quote":"I would be in favor of moving forward with pursuing one of these two options and being able to develop a plan and come back to us.","context":"Jones had asked whether patrol was ruled out because of cost, effectiveness, or both, and whether any expert had recommended horizontal netting. Staff answered both on patrol and said the recommendation against netting was unanimous.","outcome":"He supported pursuing a design and returning with further refinement. This was not final approval or selection of a particular design.","basis":"The author confirmed the highlighted 01:18:55–01:19:30 passage against the official recording. This excerpt is a continuous portion of the checked text. The timestamp is an approximate passage locator.","refs":"18","topic":"design","earlier":"Jones had just clarified the reasons for rejecting patrol as a substitute and asked whether any expert had recommended netting. Both vertical webmesh and metal pickets remained under consideration.","response":"He proposed using the feedback to refine components and variations and return with a plan. His request for refinement accompanied support for proceeding.","links":[{"label":"Patrol clarification","source":"v2024","time":"01:16:54"},{"label":"Netting clarification","source":"v2024","time":"01:18:41"},{"label":"Meeting minutes","source":"m2024"}],"sortDate":"2024-07-17","body":"Public Safety Committee"}]}};
const otherSpeakers={"delgado":{"name":"J. Delgado","role":"Design Commission chair","remarks":[{"id":"delgado-alternatives","title":"Asking about horizontal and landscape alternatives","meeting":"vjan24","time":"00:41:27","topic":"netting","quote":null,"context":"Delgado acknowledged the staff work and asked whether the team had considered horizontal protection or landscaping. She compared the discussion with the Golden Gate Bridge.","earlier":"The 2018 task force had compared netting, landscaping, and vertical barriers. November 2023 staff discussion had again addressed local netting constraints.","response":"An off-camera respondent at 00:42:33 described the earlier alternatives review and the Council’s vertical-barrier direction. Research-preference wording at 00:43:59 is author-confirmed, but the respondent’s identity and role remain unresolved.","outcome":"The commission did not reach consensus on the three designs. This exchange establishes a renewed alternatives question, not that the respondent had refused to conduct research.","links":[{"label":"Earlier alternatives comparison","source":"p2018","page":29},{"label":"Earlier netting discussion","source":"v2023","time":"00:33:24"},{"label":"Off-camera response","source":"vjan24","time":"00:42:33"},{"label":"Research-preference wording","source":"vjan24","time":"00:43:59"},{"label":"Commission minutes","source":"mjan24"}],"refs":"5, 14, 33","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2024-01-09","date":"January 9, 2024","body":"Design Commission"},{"id":"delgado-previous-council","title":"Questioning the earlier Council direction","meeting":"vjan24","time":"00:45:34","topic":"design","quote":null,"context":"Delgado referred to the “previous City Council” while questioning the restriction of the current design work to vertical barriers.","earlier":"The Council adopted the task-force recommendation in April 2018. Its policy choice and the later selection of a particular design were separate decisions.","response":"The exchange returned to whether earlier direction should constrain the options now under review. The off-camera respondent’s name and role are not established.","outcome":"No revised Council policy resulted from this commission discussion. Its minutes record no consensus on the designs.","links":[{"label":"Adopted Council direction","source":"m2018","page":5},{"label":"Commission minutes","source":"mjan24"}],"refs":"6, 33","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2024-01-09","date":"January 9, 2024","body":"Design Commission"},{"id":"delgado-cacti","title":"Suggesting cacti and relaying a housing suggestion","meeting":"vjan24","time":"00:47:03","topic":"landscaping","quote":"It could be cacti below it.","context":"Delgado suggested cacti below the bridge and relayed a public suggestion for an apartment building below it. These were suggestions made during design discussion.","earlier":"The task-force report had found no verifying data for trees as a cushion or deterrent and identified portions of the bridge where planting was not possible. It allowed a possible supplemental role.","response":"A respondent discussed existing bungalows at 00:47:29. The later response, around 00:47:50, returned to the safety reason for keeping people on the bridge deck. The respondent remains unidentified.","outcome":"Neither cacti nor housing became an adopted protection measure in this meeting. The earlier trees review does not experimentally test every later landscape suggestion.","links":[{"label":"Earlier landscaping finding","source":"r2018","page":3},{"label":"Existing-building response","source":"vjan24","time":"00:47:29"},{"label":"Deck-safety response","source":"vjan24","time":"00:47:50"}],"refs":"5, 33","kind":"Working-transcript excerpt","basis":"Short continuous excerpt from the preserved January 9 focused transcript and speaker record, which includes earlier listening notes. The retained source note supplies the approximate player locator. No new listening was performed. The responding voice is not identified as staff or a consultant.","sortDate":"2024-01-09","date":"January 9, 2024","body":"Design Commission"},{"id":"delgado-three-designs","title":"Objecting to all three presented designs","meeting":"vjan24","time":"01:06:28","topic":"design","quote":"I’m having a problem too with all three of these solutions","context":"Delgado said she was having a problem with all three solutions and discussed their materials, appearance, and relationship to the bridge.","earlier":"The replacement design team had developed three concepts through the 2023 review process. The Council’s original safety direction remained separate from design approval.","response":"Her objection concerned the presented solutions. It does not establish rejection of every finding about suicide prevention.","outcome":"The Design Commission reached no consensus. The project returned to further review rather than receiving a final design approval.","links":[{"label":"Design memo","source":"jan24memo"},{"label":"Commission minutes","source":"mjan24"}],"refs":"13, 33","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The time is an approximate passage locator. Caption cue starts can differ from the retained player locator. No new listening was performed for this website.","sortDate":"2024-01-09","date":"January 9, 2024","body":"Design Commission"}]},"kennedy":{"name":"John J. Kennedy","role":"Councilmember","remarks":[{"id":"kennedy-review","title":"Narrowing the options and seeking local expertise","date":"August 18, 2021","time":"01:16:41","meeting":"v2021","kind":"Quotation","quote":"one last time out","context":"Kennedy supported narrowing the options and placing the project on a timetable. He also supported another opportunity for local expertise to contribute to the two-option approach Madison had discussed.","outcome":"The committee did not select a permanent design. More design work and community input followed.","basis":"Quoted phrase and locator retained in the reviewed source note. The brief excerpt is presented with Kennedy’s support for narrowing and a timetable, rather than as a complete statement of his position.","refs":"9, 11","sortDate":"2021-08-18","body":"Public Safety Committee","topic":"design","earlier":"The Council’s 2018 direction had been followed by commission review and full-scale mockups. The committee was now considering which designs should proceed.","response":"Madison had proposed narrowing the field. Mermell also explained the cost and coverage concerns about staffing as a replacement for a barrier.","links":[{"label":"Staff report and advisory feedback","source":"r2021"},{"label":"Madison on narrowing","source":"v2021","time":"01:08:35"},{"label":"Mermell on staffing","source":"v2021","time":"01:27:11"}]},{"id":"kennedy-staffing","title":"Staffing, liability, and further review","date":"August 18, 2021","time":"01:41:11","meeting":"v2021","kind":"Quotation","quote":"get it right","context":"Kennedy’s preceding discussion, beginning at 01:39:01, raised liability and intervention concerns about staffing. He acknowledged the effort to save lives while questioning how personnel could safely intervene.","outcome":"He called for another round of consideration. Earlier in the meeting, he had been ready to move away from his enclosure concept and narrow the field to vertical-barrier options.","basis":"Quoted phrase and approximate locator retained in the reviewed source note. These selected remarks do not identify a private motive or measure how much delay any individual caused.","refs":"9, 11","sortDate":"2021-08-18","body":"Public Safety Committee","topic":"staffing","earlier":"The Council’s 2018 direction had been followed by commission review and full-scale mockups. The committee was now considering which designs should proceed.","response":"Madison had proposed narrowing the field. Mermell also explained the cost and coverage concerns about staffing as a replacement for a barrier.","links":[{"label":"Staff report and advisory feedback","source":"r2021"},{"label":"Madison on narrowing","source":"v2021","time":"01:08:35"},{"label":"Mermell on staffing","source":"v2021","time":"01:27:11"}]},{"id":"kennedy-enclosure","title":"Requesting a fuller enclosure comparison","meeting":null,"time":null,"topic":"design","quote":null,"context":"The February 2020 minutes record Kennedy’s request for cost information on an enclosure option.","earlier":"The first design cycle was developing a permanent barrier after the Council’s 2018 policy direction.","response":"Staff and the design consultant were asked to return with a fuller comparison. The written minutes are the evidence for this request.","outcome":"The August 2021 presentation included a refined enclosure concept and a design-goal comparison. This is an example of reconsideration producing additional design information.","links":[{"label":"Preserved February 2020 minutes · pp. 2–3","source":"dropbox"},{"label":"Later design-goal comparison","source":"v2021","time":"00:48:33"}],"refs":"10–11","kind":"Minutes summary","basis":"Inherited reading of the City Clerk-supplied February 3, 2020 minutes, pages 2–3, retained in Source 10. No recording was recovered. The Dropbox link opens the preserved-record folder, not a specific PDF.","sortDate":"2020-02-03","date":"February 3, 2020","body":"Public Safety Committee"}]},"maloyan":{"name":"Ara Maloyan","role":"Public Works director","remarks":[{"id":"maloyan-review","title":"Presenting the task-force alternatives review","meeting":"v2018","time":"01:01:16","topic":"design","quote":null,"context":"Maloyan presented the task-force recommendations following its comparison of physical barriers, netting, planting, patrols, technology, and self-help measures.","earlier":"The group had gathered public suggestions and compared options using safety, appearance, environmental, rescue, and implementation considerations.","response":"Its recommendation centered on restricting access at the bridge edge while allowing complementary measures.","outcome":"The Council adopted the recommendation later in the meeting. That policy direction still required a detailed design.","links":[{"label":"Task-force report","source":"r2018"},{"label":"Alternatives presentation","source":"p2018"},{"label":"Adopted motion","source":"m2018","page":5}],"refs":"5–7","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"},{"id":"maloyan-landscape","title":"Explaining the limits on planting below the bridge","meeting":"v2018","time":"01:04:17","topic":"landscaping","quote":null,"context":"The Public Works presentation identified roughly 20 percent of the span where trees could not be planted.","earlier":"The task-force report had found no verifying data for the proposed cushioning or deterrence role and had considered the time needed for trees to mature.","response":"The written recommendation treated planting as a possible supplement to a vertical barrier.","outcome":"Later landscape questions should be read against these limits and against the actual later proposal, rather than treated as identical ideas.","links":[{"label":"Landscaping findings","source":"r2018","page":3},{"label":"Later Madison question","source":"v2023","time":"00:33:24"},{"label":"Later Delgado suggestions","source":"vjan24","time":"00:47:03"}],"refs":"5, 7, 14, 33","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"},{"id":"maloyan-consultant-scope","title":"Explaining what the next consultant would design","meeting":"v2018","time":"01:20:58","topic":"design","quote":null,"context":"In response to McAustin, Maloyan said the next phase would develop vertical-barrier options.","earlier":"The task force had compared the types of intervention. The next question concerned the design within the recommended approach.","response":"At 01:23:11 he explained that several options would return to the community for review.","outcome":"The Council approved the policy direction, with design development, environmental work, and further public review still ahead.","links":[{"label":"McAustin’s scope question","source":"v2018","time":"01:20:21"},{"label":"Range-of-options answer","source":"v2018","time":"01:23:11"},{"label":"Next-phase tasks","source":"r2018","page":3}],"refs":"5–7","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"}]},"tornek":{"name":"Terry Tornek","role":"Mayor","remarks":[{"id":"tornek-consensus","title":"Anticipating a harder design debate","meeting":"v2018","time":"01:36:06","topic":"design","quote":"This is probably the highest level of consensus we’ll achieve in this process, I predict.","context":"Tornek predicted that agreement would become more difficult once specific designs were presented.","earlier":"The Council had heard the task-force recommendation, questions about effectiveness, and the scope of the next design phase.","response":"His observation distinguished agreement on a safety approach from agreement on what a permanent structure should look like.","outcome":"The Council nevertheless adopted the task-force direction unanimously. Years of design consideration followed.","links":[{"label":"Council minutes","source":"m2018","page":5},{"label":"Later “harbinger” remark","source":"v2018","time":"01:39:13"}],"refs":"6–7","kind":"Retained quotation","basis":"Quotation retained in the sent account and preserved April 2018 working transcript. The official-player locator is retained in Source 7. No new listening was performed.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"},{"id":"tornek-urgency","title":"Asking for a shorter consultant schedule","meeting":null,"time":null,"topic":"design","quote":null,"context":"The April 2019 minutes record Tornek’s concern that the proposed schedule was too slow given the urgency of the issue.","earlier":"The City had set aside design money in 2018 and completed a consultant solicitation and interviews.","response":"Madison cautioned about rushing a historic-landmark project but supported a revised schedule, budget review, and grant search.","outcome":"In May, staff returned with a ten-month reduction in the design schedule and a lower proposed consultant contract. Tornek seconded the revised recommendation on May 15.","links":[{"label":"Preserved April and May 2019 minutes · pp. 2–3","source":"dropbox"},{"label":"Revised contract report","source":"r2019","page":2},{"label":"Revised schedule presentation","source":"v2019","time":"00:50:01"}],"refs":"8","kind":"Minutes summary","basis":"Inherited original-minutes reading retained in Source 8. No recording is available in the reviewed record for the April 17 or May 15 committee exchanges. The Dropbox link opens the preserved-record folder.","sortDate":"2019-04-17","date":"April 17, 2019","body":"Public Safety Committee"}]},"wilson":{"name":"Andy Wilson","role":"Councilmember","remarks":[{"id":"wilson-substitution","title":"Asking whether deaths would move elsewhere","meeting":"v2018","time":"01:24:11","topic":"effectiveness","quote":null,"context":"Wilson asked whether restricting access at this bridge would simply move the problem to another location.","earlier":"The task-force recommendation concerned access restriction at the bridge. Effects at nearby sites and across a region are separate outcomes.","response":"Mermell joined the discussion at 01:25:58. Wilson called on Public Health at 01:26:46, and Michael Johnson began answering at 01:27:14.","outcome":"Johnson described evidence of broader reductions. This records the public answer given in 2018, not a new review establishing the same outcome in every setting.","links":[{"label":"Public Health answer","source":"v2018","time":"01:27:14"},{"label":"Gordo’s regional follow-up","source":"v2018","time":"01:31:15"},{"label":"Johnson’s Toronto reference","source":"v2018","time":"01:32:15"}],"refs":"7","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"},{"id":"wilson-timetable","title":"Calling attention to the length of the project","meeting":"v2019","time":"00:51:54","topic":"design","quote":"almost a four or five year project","context":"Wilson described the undertaking as “almost a four or five year project,” even after staff shortened the proposed design schedule.","earlier":"The April committee had asked staff to revisit the schedule and budget.","response":"Staff reported a ten-month shorter design period, a contract reduction from $700,000 to $500,000, and an anticipated August 2020 construction start.","outcome":"The Council approved the consultant contract. That forecast was not a funded construction deadline or evidence that construction actually began in August 2020.","links":[{"label":"Staff report","source":"r2019","page":2},{"label":"Schedule and contract changes","source":"v2019","time":"00:50:01"},{"label":"Construction forecast","source":"v2019","time":"00:51:05"}],"refs":"8","kind":"Retained quotation","basis":"Short quotation and approximate recording locator retained in Source 8. The written report supports the schedule and contract changes. No new listening was performed.","sortDate":"2019-05-20","date":"May 20, 2019","body":"City Council"}]},"mcaustin":{"name":"Margaret McAustin","role":"Councilmember","remarks":[{"id":"mcaustin-scope","title":"Asking what the consultant would actually study","meeting":"v2018","time":"01:20:21","topic":"design","quote":null,"context":"McAustin asked what work the design consultant would undertake, then asked at 01:22:55 whether a range of options would be developed.","earlier":"The task force had already compared intervention types and recommended a vertical barrier with end treatments.","response":"Maloyan answered at 01:20:58 that the next phase concerned vertical barriers and at 01:23:11 that different designs would return for community review.","outcome":"This exchange records the intended distinction between choosing the safety approach and developing its design.","links":[{"label":"Maloyan’s scope answer","source":"v2018","time":"01:20:58"},{"label":"McAustin’s options follow-up","source":"v2018","time":"01:22:55"},{"label":"Maloyan’s options answer","source":"v2018","time":"01:23:11"}],"refs":"7","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"}]},"markarian":{"name":"Kris Markarian","role":"Public Works","remarks":[{"id":"markarian-procurement","title":"Explaining a pandemic procurement and fabrication delay","meeting":"v2021","time":"00:14:14","topic":"design","quote":null,"context":"Markarian described delays obtaining materials and fabricating the mockups during the pandemic.","earlier":"The project had been through design development and was using full-scale mockups for review.","response":"The explanation concerns procurement and fabrication. It does not independently establish that all design work stopped.","outcome":"The committee reviewed the design results in August 2021 and sought additional work.","links":[{"label":"August 2021 staff report","source":"r2021"}],"refs":"24","kind":"Discussion summary","basis":"The author confirmed the highlighted 00:14:14–00:14:32 passage against the official player. This summary preserves the procurement and fabrication scope of that check. No fresh listening was performed.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"markarian-staffing","title":"Explaining why staffing had not been recommended as a replacement","meeting":"v2023","time":"00:47:01","topic":"staffing","quote":null,"context":"Markarian said the task force had considered staffing and described the problem of continuous coverage, the bridge’s curve, multiple personnel, liability, and incidents outside ordinary hours.","earlier":"Patrol and active intervention had been part of the original alternatives review. Mermell had also addressed a staffing proposal in August 2021.","response":"Officials continued asking about trained security and a daytime human presence. The distinction between complementing a barrier and replacing it remained important.","outcome":"The committee requested more staffing analysis. Staff presented annual cost estimates in July 2024.","links":[{"label":"Earlier Mermell response","source":"v2021","time":"01:27:11"},{"label":"Gordo’s further question","source":"v2023","time":"00:51:52"},{"label":"July 2024 presentation","source":"p2024"}],"refs":"11, 15–16","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"markarian-buys-time","title":"Confirming that a barrier creates time for intervention","meeting":"v2023","time":"01:01:26","topic":"effectiveness","quote":"Yes, it buys time","context":"Markarian agreed that a barrier buys time during an incident.","earlier":"Madison had questioned how quickly personnel could reach someone and how staffing would work without a barrier.","response":"This answer describes an opportunity for intervention created by restricting access. It does not isolate the effect of staffing or establish staffing as a substitute.","outcome":"The subsequent analysis continued to consider staffing costs and physical protection separately.","links":[{"label":"Madison’s preceding question","source":"v2023","time":"00:52:29"},{"label":"July 2024 staffing analysis","source":"p2024"}],"refs":"15","kind":"Author-checked quotation","basis":"Phrase and approximate player locator retained in the author-checked November 2023 passage. This website did not perform new listening.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"markarian-structural","title":"Identifying unfinished engineering questions about netting","meeting":"v2024","time":"00:27:24","topic":"netting","quote":null,"context":"Markarian explained that structural connections had not been designed and that further studies were needed to determine whether modifications to the bridge would be required.","earlier":"Staff had presented preliminary engineering and local constraints for a horizontal net.","response":"These were limits of the preliminary assessment. They are not proof that a finished net design had established impossibility.","outcome":"Staff still recommended against netting after considering engineering, rescue, and other factors.","links":[{"label":"Engineering presentation","source":"p2024"},{"label":"Fire’s rescue assessment","source":"v2024","time":"00:34:00"}],"refs":"16–18","kind":"Discussion summary","basis":"The author confirmed the highlighted 00:27:24–00:27:57 passage against the official recording. This summary preserves the unfinished connections and further-study qualification. No new listening was performed.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"markarian-netting-recommendation","title":"Reporting the expert recommendation against a local net","meeting":"v2024","time":"00:51:03","topic":"netting","quote":null,"context":"Markarian reported a unanimous expert-review recommendation against horizontal netting as a viable measure at this bridge.","earlier":"The presentation had covered local structure, bridge geometry, rescue access, and consultation about Golden Gate.","response":"That recommendation is distinct from the committee’s authority to choose a design and from a general finding about whether nets can work elsewhere.","outcome":"Jones later asked whether any expert had recommended netting. Staff again described the recommendation as unanimous.","links":[{"label":"Staff presentation","source":"p2024"},{"label":"Jones’s later question","source":"v2024","time":"01:18:41"}],"refs":"16, 18","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"markarian-exhausted","title":"Responding when below-bridge alternatives returned","meeting":"v2024","time":"01:06:47","topic":"landscaping","quote":"we have truly exhausted looking at various mitigation measures","context":"After Madison asked about ground cover and other below-bridge impediments, Markarian said the City had spent years reviewing mitigation measures with specialists.","earlier":"The earlier task-force report had assessed landscaping. The current presentation had also returned to netting, rescue, staffing, and technology.","response":"Her answer emphasized the work already performed. The continuing discussion still included questions about particular below-bridge arrangements.","outcome":"No permanent design was selected at this meeting. The statement does not prove every possible intervention had been tested.","links":[{"label":"Madison’s ground-cover question","source":"v2024","time":"01:06:01"},{"label":"2018 landscaping findings","source":"r2018","page":3},{"label":"July presentation","source":"p2024"}],"refs":"5, 18","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The time is an approximate passage locator. Caption cue starts can differ from the retained player locator. No new listening was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"}]},"mermell":{"name":"Steve Mermell","role":"City manager","remarks":[{"id":"mermell-opening","title":"Requesting discussion and direction on the designs","meeting":"v2021","time":"00:07:39","topic":"design","quote":"get it right","context":"Mermell opened the item by seeking committee discussion and direction on the permanent designs.","earlier":"Staff had completed substantial design work, commission review, and full-scale mockups.","response":"His “get it right” phrase introduced the request for direction. It was not itself a finding that another round of work was redundant.","outcome":"The committee did not select a final design and requested further consideration.","links":[{"label":"Staff report and alternatives","source":"r2021"},{"label":"Closing summary","source":"v2021","time":"01:43:48"}],"refs":"9, 11","kind":"Retained quotation","basis":"Short phrase and approximate player locator retained in Source 11. The opening passage was also consulted in the preserved captions. No fresh listening was performed.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"mermell-staffing","title":"Responding to the proposal for around-the-clock staffing","meeting":"v2021","time":"01:27:11","topic":"staffing","quote":null,"context":"Mermell said staffing had been suggested before, would likely cost several hundred thousand dollars annually, and was not feasible as a replacement for physical protection.","earlier":"Hampton had proposed staffing the bridge 24 hours a day at 01:26:44.","response":"The discussion continued with Gordo’s Host/Guide-style idea and questions about how staff could intervene.","outcome":"Further examination of staffing alongside a barrier remained in the discussion. The permanent design remained unresolved.","links":[{"label":"Hampton’s proposal","source":"v2021","time":"01:26:44"},{"label":"Later coverage explanation","source":"v2023","time":"00:47:01"}],"refs":"11, 15","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"},{"id":"mermell-return","title":"Explaining why a three-month return was too aggressive","meeting":"v2021","time":"01:43:48","topic":"design","quote":"I do think three months is probably too aggressive.","context":"In his closing summary, Mermell described the further work and said the proposed three-month timetable was probably too aggressive.","earlier":"Committee members had asked for more design work, additional expertise, and further consideration of staffing.","response":"He connected the return schedule to the work now being requested. The temporary fence would remain during that process.","outcome":"This records staff’s stated timing concern, not a calculation of how much delay any individual caused.","links":[{"label":"Committee record","source":"m2021"},{"label":"August staff report","source":"r2021"}],"refs":"11","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The time is an approximate passage locator. Caption cue starts can differ from the retained player locator. No new listening was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"}]},"olmos":{"name":"Tony Olmos","role":"Public Works director","remarks":[{"id":"olmos-next-steps","title":"Setting out the work for the next return","meeting":"v2023","time":"01:02:09","topic":"design","quote":null,"context":"Olmos proposed continuing the planned meetings and returning with survey results, responses to the committee’s questions, and Public Health and other expert input.","earlier":"The committee had discussed the three designs, previously studied alternatives, staffing, and the interpretation of suicide-prevention research.","response":"Jones had supported continuing the commission reviews and survey. Olmos’s closing proposal collected those next steps into a return plan.","outcome":"The record shows a stated plan for further work. It does not establish that a permanent design was approved or that all later milestones were completed.","links":[{"label":"Question about continuing or pausing","source":"v2023","time":"00:54:37"},{"label":"Jones’s response","source":"v2023","time":"00:55:35"},{"label":"Planned next steps","source":"p2023","page":34}],"refs":"6, 14","kind":"Discussion summary","basis":"The author manually checked the speaker and approximate player locator for the 01:02:09 closing proposal, as retained in Source 14. No new listening was performed.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"olmos-pause","title":"Asking whether staff should continue or pause","meeting":"v2023","time":"00:54:37","topic":"design","quote":null,"context":"Olmos asked whether staff should continue through the scheduled commission reviews and survey or pause the process.","earlier":"The committee had raised further questions about alternatives and staffing while three new designs were being considered.","response":"Jones recommended continuing to the commissions and hearing the survey results at 00:55:35.","outcome":"Commission review and the survey proceeded. This exchange records a concrete request for direction rather than an absence of staff work.","links":[{"label":"Jones’s response","source":"v2023","time":"00:55:35"},{"label":"2023 presentation","source":"p2023"}],"refs":"14","kind":"Discussion summary","basis":"The author manually checked this November 2023 speaker handoff and approximate player locator, as retained in Source 14. This website presents a summary and performed no new listening.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"},{"id":"olmos-health","title":"Agreeing to bring Public Health into the next review","meeting":"v2023","time":"00:57:36","topic":"effectiveness","quote":null,"context":"Olmos responded to questions about Public Health involvement and whether protection at one location moves deaths elsewhere.","earlier":"Public Health had discussed regional effects and substitution with the Council in April 2018.","response":"Staff agreed to include health professionals when the project returned. Earlier research did not eliminate the need to state its limits or explain it to the current discussion.","outcome":"A suicide prevention specialist participated in the July 2024 presentation.","links":[{"label":"2018 Public Health answer","source":"v2018","time":"01:27:14"},{"label":"Jones’s question","source":"v2023","time":"00:56:47"},{"label":"July education discussion","source":"v2024","time":"00:42:41"}],"refs":"7, 14, 19","kind":"Discussion summary","basis":"The author manually checked this November 2023 speaker handoff and approximate player locator, as retained in Source 14. This website presents a summary and performed no new listening.","sortDate":"2023-11-15","date":"November 15, 2023","body":"Public Safety Committee"}]},"johnson":{"name":"Michael Johnson","role":"Public Health director","remarks":[{"id":"johnson-regional","title":"Answering the substitution and regional-effect questions","meeting":"v2018","time":"01:27:14","topic":"effectiveness","quote":null,"context":"Johnson described research suggesting that barriers at bridges known for suicide could reduce broader deaths rather than merely shift them elsewhere.","earlier":"Wilson had asked about substitution. Gordo followed with a regional-effect question at 01:31:15.","response":"Johnson answered the follow-up at 01:31:51 and referred to Toronto research at 01:32:15.","outcome":"This establishes what the Council was told in 2018. Different sites, follow-up periods, regional jumping deaths, and all-method deaths must remain distinct when evaluating the original research.","links":[{"label":"Wilson’s question","source":"v2018","time":"01:24:11"},{"label":"Gordo’s follow-up","source":"v2018","time":"01:31:15"},{"label":"Johnson’s study reference","source":"v2018","time":"01:32:15"}],"refs":"7, 29–30","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"}]},"line":{"name":"Steve Line","role":"Design consultant","remarks":[{"id":"line-comparison","title":"Comparing the refined enclosure against design goals","meeting":"v2021","time":"00:48:33","topic":"design","quote":null,"context":"Line compared the developed concepts, including a refined enclosure, against the project’s design goals.","earlier":"Kennedy had requested a fuller enclosure cost comparison in February 2020. The design team subsequently developed more detail.","response":"The presentation compared safety, appearance, and the relationship to the historic bridge. A concept comparison was not final design approval.","outcome":"Kennedy later supported narrowing to vertical-barrier options. This sequence preserves an instance in which reconsideration added design information.","links":[{"label":"Preserved February 2020 minutes","source":"dropbox"},{"label":"August 2021 report","source":"r2021"},{"label":"Kennedy on narrowing","source":"v2021","time":"01:16:41"}],"refs":"10–11","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2021-08-18","date":"August 18, 2021","body":"Public Safety Committee"}]},"augustin":{"name":"Chad Augustin","role":"Fire chief","remarks":[{"id":"augustin-rescue","title":"Explaining the rescue concerns with horizontal netting","meeting":"v2024","time":"00:34:00","topic":"netting","quote":null,"context":"Augustin discussed the safety of the person in crisis and responding crews, access to a net, the use of two ladder trucks, extended operations, and training requirements.","earlier":"The City had consulted about netting and developed a preliminary local engineering assessment.","response":"At approximately 00:35:48, he said he could not recommend horizontal netting from a public-safety standpoint.","outcome":"The recommendation was about local rescue operations. It does not establish that nets are universally ineffective or that all engineering questions had been resolved.","links":[{"label":"Fire’s recommendation","source":"v2024","time":"00:35:48"},{"label":"Staff presentation","source":"p2024"},{"label":"Unfinished structural questions","source":"v2024","time":"00:27:24"}],"refs":"16–18","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"augustin-vertical","title":"Clarifying support for a vertical barrier","meeting":"v2024","time":"01:09:16","topic":"netting","quote":"we absolutely are in support of a barrier","context":"Augustin clarified that Fire’s concern was with horizontal netting and that the department supported a vertical barrier.","earlier":"Gordo’s preceding question had raised the netting and rescue issue. Staff had already explained the local rescue difficulties.","response":"The clarification prevents the recommendation against netting from being read as opposition to physical protection generally.","outcome":"The committee continued discussing the options without selecting a permanent design.","links":[{"label":"Earlier Fire explanation","source":"v2024","time":"00:34:00"},{"label":"Committee minutes","source":"m2024"}],"refs":"18, 22","kind":"Caption excerpt","basis":"Excerpt read in the preserved City-hosted captions, with punctuation and capitalization adjusted for reading. The time is an approximate passage locator. Caption cue starts can differ from the retained player locator. No new listening was performed for this website.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"},{"id":"augustin-cushion","title":"Describing the rescue cushion’s operational limits","meeting":"v2024","time":"01:20:04","topic":"netting","quote":null,"context":"Augustin described a roughly 100-foot cushion rating, bridge portions reaching roughly 150 feet, and constraints on positioning equipment below the bridge.","earlier":"Hampton had returned to below-bridge measures after the netting and rescue presentation.","response":"Hampton then asked whether higher-capacity equipment existed. Staff did not know and agreed to investigate.","outcome":"The reviewed record does not establish that a higher-capacity cushion was acquired. The May 2026 Fire equipment list names a cushion but supplies no rating.","links":[{"label":"Higher-capacity question","source":"v2024","time":"01:20:55"},{"label":"May 2026 equipment list · packet p. 22","source":"fire2026"}],"refs":"21","kind":"Discussion summary","basis":"Summary follows the retained Source 21 locators and local operating limits. The May 2026 equipment-list reference is a separate documentary check, not proof that the 2024 question was answered. No new listening was performed.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"}]},"kramer":{"name":"Sandri Kramer","role":"Suicide prevention specialist","remarks":[{"id":"kramer-education","title":"Explaining the need for public education about prevention","meeting":"v2024","time":"00:42:41","topic":"effectiveness","quote":"public education issue","context":"Kramer described a public education issue in understanding suicide prevention and the role of barriers in creating time for intervention.","earlier":"The survey had shown uncertainty about both the need for a vertical barrier and whether it would work. The responses were public opinion, not a clinical-outcome study.","response":"Her discussion placed intervention time and the impact on responders alongside the project’s engineering and design questions.","outcome":"This supports reading the survey alongside research and professional explanation. It does not turn survey preferences into evidence of effectiveness.","links":[{"label":"Survey presentation","source":"p2024"},{"label":"Earlier Public Health discussion","source":"v2018","time":"01:27:14"}],"refs":"19","kind":"Retained quotation","basis":"Short phrase and player locator retained in Source 19. Selected preserved captions were consulted. This was not a new full-presentation or audio verification.","sortDate":"2024-07-17","date":"July 17, 2024","body":"Public Safety Committee"}]},"mossman":{"name":"Sue Mossman","role":"Pasadena Heritage","remarks":[{"id":"mossman-preservation","title":"Describing the preservation and safety tradeoff","meeting":null,"time":null,"topic":"design","quote":null,"context":"In a 2018 interview, Mossman discussed the difficulty of protecting people while respecting the bridge’s historic design.","earlier":"The Council had adopted the task-force recommendation, with the permanent design still to be developed.","response":"Her comments described a preservation perspective. They were not a clinical finding or a City decision.","outcome":"The 2021 committee minutes later record her appreciation for the staff and design team, the lack of task-force consensus on the designs, and her call for further exploration.","links":[{"label":"Los Angeles magazine interview","source":"lamag"},{"label":"August 2021 minutes","source":"m2021","page":2},{"label":"Winter 2026 preservation commentary · p. 8","source":"wpra"}],"refs":"23","kind":"Interview summary","basis":"The June 18, 2018 Los Angeles magazine interview was read as text. The later August 2021 minutes supply documentary context, not an inferred timestamp. The Winter 2026 column is a separately retained source. No recorded utterance is claimed here.","sortDate":"2018-06-18","date":"June 18, 2018","body":"Published interview"}]},"masuda":{"name":"Gene Masuda","role":"Councilmember","remarks":[{"id":"masuda-access","title":"Asking whether pedestrian access could be prohibited","meeting":"v2018","time":"01:14:36","topic":"design","quote":null,"context":"Masuda asked whether pedestrians could simply be prohibited from the bridge.","earlier":"The task force was recommending a physical barrier that would allow the bridge to continue serving its public uses.","response":"Maloyan answered that a pedestrian ban would not prevent access without closing the bridge to vehicle traffic as well, which he called impossible.","outcome":"The Council proceeded with the barrier recommendation. This was a transportation and access explanation, not a study measuring the effects of a pedestrian ban.","links":[{"label":"Task-force report","source":"r2018"},{"label":"Council minutes","source":"m2018"}],"refs":"7","kind":"Discussion summary","basis":"Discussion summary carried from the retained source note and supporting record. The time is an approximate official-player passage locator. No new listening was performed for this website.","sortDate":"2018-04-23","date":"April 23, 2018","body":"City Council"}]}};
