const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const externalLink = url => /^https?:\/\//i.test(url) && new URL(url).hostname !== 'coloradostreetbridgeproject.com';
